// Wordle word lists. ALL = full valid-guess pool; COMMON = frequency-filtered
// subset (Google n-gram occurrence >= 1e-7) unioned with the historical NYT
// answer pool. COMMON approximates the wordlebot's narrower answer pool;
// ALL catches edge cases the bot may not consider.
// Sources: https://gist.github.com/dracos/dd0668f281e685bad51479e5acaadb93
//          https://github.com/steve-kasica/wordle-words (frequencies + history)
const ALL_RAW = '';
const COMMON_RAW = '';
const decode = (s: string): readonly string[] =>
  Array.from({ length: s.length / 5 }, (_, i) => s.slice(i * 5, i * 5 + 5));
export const WORDS_ALL: readonly string[] = decode(ALL_RAW);
export const WORDS_COMMON: readonly string[] = decode(COMMON_RAW);
